begin;
create table public.sale_returns(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid not null references public.branches(id),sale_id uuid not null references public.sales(id),return_number text not null,refund_method text not null check(refund_method in('cash','card','ewallet','store_credit','other')),refund_amount numeric(14,2) not null check(refund_amount>=0),reason text not null,processed_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(organization_id,return_number));
create table public.sale_return_items(id uuid primary key default gen_random_uuid(),return_id uuid not null references public.sale_returns(id) on delete cascade,sale_item_id uuid not null references public.sale_items(id),product_id uuid not null references public.products(id),quantity numeric(14,3) not null check(quantity>0),unit_price numeric(14,2) not null,condition text not null check(condition in('resellable','damaged')),line_refund numeric(14,2) not null);
alter table public.sale_returns enable row level security;alter table public.sale_return_items enable row level security;
create policy returns_read on public.sale_returns for select to authenticated using(public.current_user_belongs_to_organization(organization_id) or public.current_user_is_platform_administrator());
create policy return_items_read on public.sale_return_items for select to authenticated using(exists(select 1 from public.sale_returns r where r.id=return_id and(public.current_user_belongs_to_organization(r.organization_id)or public.current_user_is_platform_administrator())));
create or replace function public.get_returns_workspace(p_organization_id uuid,p_branch_id uuid)
returns jsonb language plpgsql stable security definer set search_path=public as $$ begin if not public.current_user_can_manage_inventory(p_organization_id)then raise exception 'Manager access required';end if;return jsonb_build_object('sales',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'receipt_number',s.receipt_number,'created_at',s.created_at,'total',s.total,'items',(select jsonb_agg(jsonb_build_object('id',i.id,'product_id',i.product_id,'product_name',i.product_name,'sku',i.sku,'quantity',i.quantity,'returned_quantity',coalesce((select sum(ri.quantity)from public.sale_return_items ri join public.sale_returns r on r.id=ri.return_id where ri.sale_item_id=i.id),0),'unit_price',i.unit_price))from public.sale_items i where i.sale_id=s.id))order by s.created_at desc)from(select * from public.sales where organization_id=p_organization_id and branch_id=p_branch_id and status='completed'order by created_at desc limit 100)s),'[]'::jsonb),'returns',coalesce((select jsonb_agg(jsonb_build_object('return_number',r.return_number,'receipt_number',s.receipt_number,'refund_amount',r.refund_amount,'refund_method',r.refund_method,'reason',r.reason,'created_at',r.created_at)order by r.created_at desc)from public.sale_returns r join public.sales s on s.id=r.sale_id where r.organization_id=p_organization_id and r.branch_id=p_branch_id),'[]'::jsonb));end;$$;
create or replace function public.create_sale_return(p_organization_id uuid,p_branch_id uuid,p_sale_id uuid,p_items jsonb,p_refund_method text,p_reason text)
returns jsonb language plpgsql security definer set search_path=public as $$ declare item jsonb;line public.sale_items;qty numeric;prior numeric;amount numeric:=0;new_qty numeric;num text;new_id uuid;cond text;begin if not public.current_user_can_manage_inventory(p_organization_id)then raise exception 'Manager access required';end if;if nullif(trim(p_reason),'')is null then raise exception 'Return reason is required';end if;if not exists(select 1 from public.sales where id=p_sale_id and organization_id=p_organization_id and branch_id=p_branch_id and status='completed')then raise exception 'Sale is unavailable for return';end if;num:='RT-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));for item in select * from jsonb_array_elements(p_items)loop select * into line from public.sale_items where id=(item->>'sale_item_id')::uuid and sale_id=p_sale_id;qty:=(item->>'quantity')::numeric;select coalesce(sum(ri.quantity),0)into prior from public.sale_return_items ri join public.sale_returns r on r.id=ri.return_id where ri.sale_item_id=line.id;if line.id is null or qty<=0 or prior+qty>line.quantity then raise exception 'Return quantity exceeds purchased quantity';end if;amount:=amount+round(qty*line.unit_price,2);end loop;insert into public.sale_returns(organization_id,branch_id,sale_id,return_number,refund_method,refund_amount,reason,processed_by)values(p_organization_id,p_branch_id,p_sale_id,num,p_refund_method,amount,trim(p_reason),auth.uid())returning id into new_id;for item in select * from jsonb_array_elements(p_items)loop select * into line from public.sale_items where id=(item->>'sale_item_id')::uuid;qty:=(item->>'quantity')::numeric;cond:=item->>'condition';insert into public.sale_return_items(return_id,sale_item_id,product_id,quantity,unit_price,condition,line_refund)values(new_id,line.id,line.product_id,qty,line.unit_price,cond,round(qty*line.unit_price,2));if cond='resellable'then update public.branch_products set quantity=quantity+qty,updated_at=now()where branch_id=p_branch_id and product_id=line.product_id returning quantity into new_qty;insert into public.inventory_movements(organization_id,branch_id,product_id,movement_type,quantity_delta,quantity_after,reason,created_by)values(p_organization_id,p_branch_id,line.product_id,'return',qty,new_qty,num||': '||trim(p_reason),auth.uid());else insert into public.inventory_disposals(organization_id,branch_id,product_id,quantity,reason,created_by)values(p_organization_id,p_branch_id,line.product_id,qty,'Damaged return '||num||': '||trim(p_reason),auth.uid());end if;end loop;return jsonb_build_object('return_number',num,'refund_amount',amount);end;$$;
revoke all on function public.get_returns_workspace(uuid,uuid),public.create_sale_return(uuid,uuid,uuid,jsonb,text,text)from public;grant execute on function public.get_returns_workspace(uuid,uuid),public.create_sale_return(uuid,uuid,uuid,jsonb,text,text)to authenticated;commit;
